create or replace function public.enforce_report_line_department() returns trigger language plpgsql security definer set search_path = public as $$ declare v_employee_department text; begin if exists (select 1 from public.profiles where id = auth.uid() and role = 'manager') then return new; end if; select e.department into v_employee_department from public.report_batches rb join public.employees e on e.id = rb.employee_id where rb.id = new.batch_id; if v_employee_department is null or v_employee_department <> new.department then raise exception 'Employees may only report tasks from their own department.'; end if; return new; end; $$; drop trigger if exists report_lines_department on public.report_lines; create trigger report_lines_department before insert on public.report_lines for each row execute function public.enforce_report_line_department();
